const originalQuestion = $input.first().json.inputData?.original_question || 'Health Report';

// If the query is from the frontend telemetry poll, return the raw telemetry array as the report
if (originalQuestion.includes('Show Server Health Report') || originalQuestion.includes('telemetry')) {
    const rawTelemetry = $('Generate Server Telemetry').all().map(item => item.json);
    return [{
        json: {
            success: true,
            timestamp: new Date().toISOString(),
            question: originalQuestion,
            report: rawTelemetry,
            report_length: rawTelemetry.length,
            status: 'COMPLETE'
        }
    }];
}

// Otherwise, return the conversational LLM report
const aiResponse = $input.first().json.output || $input.first().json;
const response = {
    success: true,
    timestamp: new Date().toISOString(),
    question: originalQuestion,
    report: aiResponse,
    report_length: JSON.stringify(aiResponse).length,
    status: 'COMPLETE'
};

console.log(`📊 Report generated: ${response.report_length} characters`);
return [{ json: response }];

// Get user input
const input = $input.first().json;
let body = input.body;

if (typeof body === 'string') {
    try {
        body = JSON.parse(body);
    } catch (e) {
        // Fallback for form-urlencoded or raw text
        if (body.includes('=')) {
            try {
                const params = {};
                body.split('&').forEach(part => {
                    const [k, v] = part.split('=');
                    params[decodeURIComponent(k)] = decodeURIComponent(v);
                });
                body = params;
            } catch (err) {}
        }
    }
}

const userQuestion = body?.question || input.query?.question || input.question || (typeof body === 'string' ? body : '');
const question = userQuestion || 'Provide a health and security report for all servers';

// Detect intent
function detectIntent(text) {
    const lowerText = text.toLowerCase();
    if (lowerText.includes('security') || lowerText.includes('threat') || lowerText.includes('risk') || lowerText.includes('login') || lowerText.includes('firewall')) {
        return 'SECURITY_REPORT';
    }
    if (lowerText.includes('health') || lowerText.includes('status') || lowerText.includes('report')) {
        return 'HEALTH_REPORT';
    }
    if (lowerText.includes('cpu') || lowerText.includes('memory') || lowerText.includes('disk')) {
        return 'METRIC_QUERY';
    }
    if (lowerText.includes('critical') || lowerText.includes('alert') || lowerText.includes('problem')) {
        return 'CRITICAL_ALERT';
    }
    if (lowerText.includes('failed') || lowerText.includes('blocked') || lowerText.includes('suspicious')) {
        return 'SECURITY_ALERT';
    }
    return 'GENERAL_QUERY';
}

function extractServer(text) {
    const words = text.split(' ');
    for (let word of words) {
        if (word.includes('server') || word.includes('prod') || word.includes('dev')) {
            const index = words.indexOf(word);
            if (index < words.length - 1) {
                const potentialServer = words[index + 1];
                const server = potentialServer.replace(/[^a-zA-Z0-9-]/g, '');
                if (server.length > 0) return server;
            }
        }
    }
    return null;
}

const reqServer = body?.server_name || input.query?.server_name || input.server_name;
const serverName = reqServer || extractServer(question) || 'all';

const processedData = {
    original_question: question,
    intent: detectIntent(question),
    server_name: serverName,
    include_security: question.toLowerCase().includes('security') || question.toLowerCase().includes('threat') || question.toLowerCase().includes('risk'),
    timestamp: new Date().toISOString()
};

console.log(`📝 User Question: ${question}`);
console.log(`🎯 Intent Detected: ${processedData.intent}`);
console.log(`🖥️ Server: ${processedData.server_name}`);

return [{ json: processedData }];

const aiOutput = $json.output || $json.text || '';

// Strip any remaining markdown that Telegram can't handle
let text = aiOutput
  .replace(/^#{1,3}\s*/gm, '')
  .replace(/\*\*/g, '')
  .replace(/\*([^*]+)\*/g, '$1')
  .replace(/`{3}[a-z]*\n?/g, '')
  .replace(/`([^`]+)`/g, '$1')
  .replace(/\|/g, ' ')
  .replace(/---+/g, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

// Add timestamp footer
const now = new Date().toISOString().replace('T', ' ').substring(0, 19);
text = text + '\n\n⏰ Report Time: ' + now + ' UTC';

return [{ json: { telegramText: text } }];

const data = $('Generate Server Telemetry').item.json;
const successLog = {
  status: 'SUCCESS',
  timestamp: new Date().toISOString(),
  server: data.server_name || 'Unknown',
  message: '✅ Metrics and Security data successfully stored and report sent',
  details: {
    id: data.id,
    cpu_usage: data.cpu?.usage_percent,
    memory_usage: data.memory?.usage_percent,
    disk_usage: data.disk?.usage_percent,
    threat_level: data.security?.threat_level,
    risk_score: data.security?.risk_score
  }
};
console.log('✅ [' + successLog.timestamp + '] ' + successLog.message + ' for ' + successLog.server);
return [{ json: successLog }];

