const lastErrorItems = $input.all();
const lastError = lastErrorItems.length > 0 ? lastErrorItems[0].json : null;

let shouldAlert = true;
let cooldownRemaining = 0;

if (lastError && lastError.timestamp) {
  const lastTime = new Date(lastError.timestamp).getTime();
  const now = Date.now();
  const diffMs = now - lastTime;
  const diffMinutes = diffMs / (1000 * 60);
  const cooldownMinutes = 15;

  if (diffMinutes < cooldownMinutes) {
    shouldAlert = false;
    cooldownRemaining = Math.round(cooldownMinutes - diffMinutes);
  }
}

return [{
  json: {
    shouldAlert,
    cooldownRemaining,
    lastErrorTimestamp: (lastError && lastError.timestamp) ? lastError.timestamp : null
  }
}];

// Fetch real host SRE metrics from the host daemon
const response = await fetch('http://host.docker.internal:9900/metrics');
const data = await response.json();
return data.map(item => ({ json: item }));
